using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace Underwater.Editor {
[InitializeOnLoad]public static class CombPlayAudit {
 static double started;static int frames;static SeaLife actor;static SkinnedMeshRenderer skin;static Vector3 firstSize;static float minimum=float.MaxValue,maximum;static int[] bodyVertices;
 static CombPlayAudit(){if(SessionState.GetBool("CombPlayAudit",false)){EditorApplication.playModeStateChanged+=Mode;EditorApplication.update+=Tick;started=EditorApplication.timeSinceStartup;}}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/Underwater_Realistic.unity");SessionState.SetBool("CombPlayAudit",true);EditorApplication.playModeStateChanged-=Mode;EditorApplication.playModeStateChanged+=Mode;EditorApplication.update-=Tick;EditorApplication.update+=Tick;started=EditorApplication.timeSinceStartup;EditorApplication.EnterPlaymode();}
 static void Mode(PlayModeStateChange state){if(state!=PlayModeStateChange.EnteredPlayMode)return;try{actor=UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Where(a=>a.kind=="Comb jelly").OrderBy(a=>(a.transform.position-OceanWorld.Centers[3]).sqrMagnitude).First();skin=actor.GetComponentInChildren<SkinnedMeshRenderer>();var weights=skin.sharedMesh.boneWeights;bodyVertices=Enumerable.Range(0,weights.Length).Where(i=>skin.bones[weights[i].boneIndex0].name.StartsWith("Body")).ToArray();firstSize=BodySize();var camera=Camera.main;var diver=UnityEngine.Object.FindFirstObjectByType<Diver>();typeof(Diver).GetMethod("SetMenu",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(diver,new object[]{false});if(!diver.GetComponent<DiverCollisionMotor>().TryTeleport(OceanWorld.Centers[3]))throw new Exception("Twilight teleport blocked");camera.transform.LookAt(skin.bounds.center);Debug.Log("COMB_PLAY_ENTERED actor="+actor.transform.position+" camera="+camera.transform.position+" skin="+skin.bounds);}catch(Exception e){Finish(1,e.ToString());}}
 static void Tick(){if(!SessionState.GetBool("CombPlayAudit",false))return;if(EditorApplication.timeSinceStartup-started>100){Finish(1,"Playmode timeout");return;}if(!EditorApplication.isPlaying||!skin)return;var size=BodySize();float width=Mathf.Max(size.x,size.z);minimum=Mathf.Min(minimum,width);maximum=Mathf.Max(maximum,width);if(++frames<180)return;try{var camera=Camera.main;camera.transform.LookAt(skin.bounds.center);if(skin.GetComponentInParent<LODGroup>())throw new Exception("Comb has a runtime distance cutoff");if(!skin.enabled||!skin.gameObject.activeInHierarchy)throw new Exception("Runtime jelly disabled");float deformation=maximum-minimum;Debug.Log("COMB_RUNTIME_BODY clock="+typeof(JellyReferenceMotion).GetField("clock",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(actor.GetComponent<JellyReferenceMotion>())+" menu="+Diver.Instance.MenuOpen+" animation="+actor.GetComponent<JellyReferenceMotion>().player.enabled+" bodyWidthRange="+deformation);if(deformation<.01f)throw new Exception("Main body remained static in Play mode");Directory.CreateDirectory("Renders/CombPlayAudit");ReefCorrectionAudit.Capture(camera,"Renders/CombPlayAudit/ActualPlay.png");int near=VisiblePixels(camera);camera.transform.position=skin.bounds.center+Vector3.right*30;camera.transform.LookAt(skin.bounds.center);int far=VisiblePixels(camera);if(near<20||far<2)throw new Exception("Jelly invisible near/far: "+near+"/"+far);Debug.Log("COMB_PLAY_VISIBILITY nearPixels="+near+" far30mPixels="+far+" bodySizeChange="+deformation);Finish(0,"COMB_PLAY_AUDITED");}catch(Exception e){Finish(1,e.ToString());}}
 static Vector3 BodySize(){var points=OctopusRepairValidation.Points(skin);var local=bodyVertices.Select(i=>actor.transform.InverseTransformPoint(points[i])).ToArray();var b=new Bounds(local[0],Vector3.zero);foreach(var p in local)b.Encapsulate(p);return b.size;}
 static int VisiblePixels(Camera camera){var others=UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None).Where(r=>r.enabled&&r!=skin).ToArray();foreach(var r in others)r.enabled=false;var clear=camera.clearFlags;var background=camera.backgroundColor;bool fog=RenderSettings.fog;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;RenderSettings.fog=false;var rt=new RenderTexture(512,512,24);camera.targetTexture=rt;var previous=RenderTexture.active;var texture=new Texture2D(512,512,TextureFormat.RGB24,false);try{camera.Render();RenderTexture.active=rt;texture.ReadPixels(new Rect(0,0,512,512),0,0);texture.Apply();return texture.GetPixels32().Count(c=>Mathf.Max(c.r,Mathf.Max(c.g,c.b))>8);}finally{camera.targetTexture=null;RenderTexture.active=previous;camera.clearFlags=clear;camera.backgroundColor=background;RenderSettings.fog=fog;foreach(var r in others)if(r)r.enabled=true;UnityEngine.Object.DestroyImmediate(texture);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
 static void Finish(int code,string message){SessionState.SetBool("CombPlayAudit",false);Debug.Log(message);EditorApplication.Exit(code);}
}
}
